export const getServerSideProps: GetServerSideProps<Props> = async () => {
  const props: Props = {
    isConnected: false,
  };

  if (cosmos.connected) {
    props.isConnected = true;
    try {
      const { resource: database } = await cosmos.database!.read();
      const containerIterator = cosmos.database!.containers.query({
        query: "SELECT * from p",
      });
      const { resources: containers } = await containerIterator.fetchAll();
      props.database = {
        isConnected: true,
        name: database?.id,
        numOfContainers: containers.length,
      };
    } catch {
      props.database = {
        isConnected: false,
      };
    }
    try {
      const { resource: container } = await cosmos.container!.read();
      props.container = {
        isConnected: true,
        name: container?.id,
      };
    } catch {
      props.database = {
        isConnected: false,
      };
    }
  }
  return {
    props,
  };
};

