async function update(
  id: string,
  data: { title?: string; content?: string },
): Promise<void> {
  await fetch(`/api/post/${id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  });
  alert("Draft saved!");
